import React, { useState } from "react";
import { X } from "lucide-react";

interface QuickAddModalProps {
  onClose: () => void;
}

const QuickAddModal: React.FC<QuickAddModalProps> = ({ onClose }) => {
  const [description, setDescription] = useState("");
  const [amount, setAmount] = useState("");
  const [category, setCategory] = useState("Food");
  const [type, setType] = useState<"expense" | "income">("expense");

  const handleSave = () => {
    // In a real app: dispatch to state manager or API
    alert(`Saved: ${type === "expense" ? "-" : "+"}$${amount} for ${description}`);
    onClose();
  };

  return (
    <div className="bg-white border border-gray-100 rounded-xl p-5 mb-5 shadow-sm">
      <div className="flex items-center justify-between mb-4">
        <span className="font-medium text-sm">Add Transaction</span>
        <button
          onClick={onClose}
          className="text-gray-400 hover:text-gray-600 transition-colors"
        >
          <X size={18} />
        </button>
      </div>

      {/* Type toggle */}
      <div className="flex gap-2 mb-4">
        {(["expense", "income"] as const).map((t) => (
          <button
            key={t}
            onClick={() => setType(t)}
            className={`flex-1 py-2 rounded-lg text-sm font-medium capitalize transition-colors ${
              type === t
                ? t === "expense"
                  ? "bg-red-100 text-red-600"
                  : "bg-emerald-100 text-emerald-600"
                : "bg-gray-50 text-gray-500 hover:bg-gray-100"
            }`}
          >
            {t}
          </button>
        ))}
      </div>

      <div className="flex flex-wrap gap-3">
        <input
          type="text"
          placeholder="Description"
          value={description}
          onChange={(e) => setDescription(e.target.value)}
          className="flex-1 min-w-[140px] px-3 py-2 text-sm border border-gray-200 rounded-lg focus:outline-none focus:border-emerald-400"
        />
        <input
          type="number"
          placeholder="Amount"
          value={amount}
          onChange={(e) => setAmount(e.target.value)}
          className="w-28 px-3 py-2 text-sm border border-gray-200 rounded-lg focus:outline-none focus:border-emerald-400"
        />
        <select
          value={category}
          onChange={(e) => setCategory(e.target.value)}
          className="px-3 py-2 text-sm border border-gray-200 rounded-lg focus:outline-none focus:border-emerald-400 bg-white"
        >
          {["Food", "Housing", "Transport", "Entertainment", "Shopping", "Health", "Income"].map(
            (c) => (
              <option key={c}>{c}</option>
            )
          )}
        </select>
        <button
          onClick={handleSave}
          className="px-4 py-2 bg-emerald-500 hover:bg-emerald-600 text-white text-sm font-medium rounded-lg transition-colors"
        >
          Save
        </button>
      </div>
    </div>
  );
};

export default QuickAddModal;
